function recordActivity(s){const stamp=s.updatedAt||s.finishedAt;if(!stamp||(!s.phase&&!s.status))return;const label=phaseLabels[s.phase]||s.phase||s.status||"상태 변경",key=[label,s.currentFileName,s.currentChunk,s.model,s.message].join("|");if(!key||key===state.lastActivityKey)return;state.lastActivityKey=key;const log=$("#activity-log");if(log.children.length===1&&log.firstElementChild.textContent==="모니터 연결 대기 중")log.replaceChildren();const first=log.firstElementChild;if(first&&first.dataset.activityKey===key)return;const item=document.createElement("li");item.dataset.activityKey=key;item.textContent=`${formatTime(stamp)} · ${label}${s.currentFileName?` · ${s.currentFileName}`:""}`;log.prepend(item);while(log.children.length>12)log.lastElementChild.remove()}
function formatBytes(value){const bytes=Number(value||0);if(!bytes)return"0 B";const units=["B","KB","MB","GB"],i=Math.min(units.length-1,Math.floor(Math.log(bytes)/Math.log(1024)));return`${(bytes/1024**i).toFixed(i?1:0)} ${units[i]}`}
